let currentLanguage = "es";
const languageButton = document.querySelector("#language-toggle");
function setLanguage(language) {
  currentLanguage = translations[language] ? language : "es";
  try { localStorage.setItem("portfolio-language", currentLanguage); } catch (error) { /* La web sigue funcionando si el almacenamiento está bloqueado. */ }
  document.documentElement.lang = currentLanguage;
  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const key = element.dataset.i18n;
    const translation = translations[currentLanguage][key];
    if (translation) element.innerHTML = translation;
    const altKey = element.dataset.i18nAlt;
    if (altKey && translations[currentLanguage][altKey]) element.setAttribute("alt", translations[currentLanguage][altKey]);
  });
  if (languageButton) {
    languageButton.textContent = currentLanguage === "es" ? "ES / EN" : "EN / ES";
    languageButton.setAttribute("aria-label", currentLanguage === "es" ? "Change language to English" : "Cambiar idioma a español");
  }
}
if (languageButton) {
  languageButton.addEventListener("click", () => setLanguage(currentLanguage === "es" ? "en" : "es"));
}
try {
  const savedLanguage = localStorage.getItem("portfolio-language");
  if (savedLanguage && translations[savedLanguage]) setLanguage(savedLanguage);
} catch (error) { /* Idioma predeterminado: español. */ }
const yearElement = document.querySelector("#year");
if (yearElement) yearElement.textContent = String(new Date().getFullYear());


// Acordeones exclusivos por nivel, sin cerrar el contenedor padre al abrir un apartado interno.
document.querySelectorAll(".project-accordions, .nested-accordions").forEach((group) => {
  group.addEventListener("toggle", (event) => {
    const opened = event.target;
    // El evento toggle se propaga: solo debe actuar el grupo que contiene directamente al details abierto.
    if (!(opened instanceof HTMLDetailsElement) || !opened.open || opened.parentElement !== group) return;

    const selector = opened.classList.contains("project-accordion")
      ? ":scope > .project-accordion"
      : ":scope > .nested-accordion";

    group.querySelectorAll(selector).forEach((item) => {
      if (item !== opened && item.open) item.open = false;
    });

    // En móvil, recoloca el inicio del desplegable recién abierto bajo la cabecera fija.
    if (window.matchMedia("(max-width: 760px)").matches) {
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          if (opened.isConnected && opened.open) {
            opened.scrollIntoView({ behavior: "smooth", block: "start" });
          }
        });
      });
    }
  }, true);
});
